1	//! `paste_attributes` — Edit ▸ Paste Attributes and Edit ▸ Paste Graphic
2	//! Properties (spec §6, table "Clips"; spec §11 G-32).
3	//!
4	//! Its own module because it is the clipboard's OTHER use: `paste` makes a
5	//! payload fit and places it, and this copies properties onto clips that
6	//! are already there and places nothing. The two share one thing, the
7	//! payload, whose shape stays `edit_paste.rs`'s to know and is read through
8	//! its [`parse_payload`]. Cut out of `edit_paste.rs` under the size rule
9	//! (core/CLAUDE.md), as a pure move, ahead of G-32.
10	//!
11	//! `paste_attributes` copies the EARLIEST payload clip's property groups
12	//! onto clips already on the timeline. It is not in `edit_props.rs` because
13	//! the material comes from the clipboard, not from a caller's patch. A
14	//! group is REPLACED whole, never merged — "make this look like that" is
15	//! the gesture, and a merge would leave the target's shadow under a source
16	//! that had none. What a target keeps is what makes it the clip it is
17	//! rather than how it looks: a text clip's `content` and the `words` that
18	//! time it (spec §11 W-6 — a timing belongs to its words); a shape's
19	//! `kind`, `width`, `height`, `from` and `to`. Video and audio travel whole,
20	//! transform included — `audio.muted` and `keep_pitch` are properties like
21	//! opacity, and `keep_pitch` only acts when the speed is not 1, which does
22	//! not travel: `speed`, `enabled`, the actions, the transition, the name,
23	//! the label and the source are not properties at all.
24	//!
25	//! **The qualifier follows the clip kind** (spec §11 GR-13): only an
26	//! adjustment clip takes one, so a picture target gets none (dropped, which
27	//! `paste_attributes`' description says — D2-1: a paste's answer is not
28	//! the place for it), and an adjustment target keeps its own when the
29	//! payload clip is a picture clip, which has none to give. Between two
30	//! adjustment clips it is copied like any other video key.
31	//!
32	//! ### The fifth group
33	//!
34	//! `graphic` (G-32) copies a graphic clip's `props`, whole, onto clips
35	//! drawn by the SAME module, and the target keeps its `name`, `width`,
36	//! `height`, `in` and `length`. It is a group a caller NAMES and never one
37	//! of the default set: props hold a graphic's words as well as its look,
38	//! and ⌥⌘V has no picker. That is why the names are [`PasteGroup`] and not
39	//! `patch::Group`: a patch has no `graphic` group (G-10), and `Group` is
40	//! matched exhaustively wherever a patch is read.
41	//!
42	//! The copied map is checked for SHAPE only — `model_graphic.rs`'s
43	//! `check_props` with no schema, then `check_count` — and only when a
44	//! target takes it, the first time one does: a paste in which no target
45	//! takes `graphic` never reads the map, as the four groups are checked
46	//! only after they have landed on a target. The write is `insert` and
47	//! `shift_remove`, `model_graphic.rs`'s rule, so a key both sides have
48	//! keeps its slot. A target key the payload lacks that an action on the
49	//! target names (`actions_graphic.rs`'s `names_prop`) is KEPT in its slot,
50	//! so the action's ramp keeps its start (spec §11 G-34 (d), amending
51	//! G-32 (e)).
52	
53	use serde::{Deserialize, Serialize};
54	use serde_json::{Map, Value};
55	
56	use crate::actions_graphic::names_prop;
57	use crate::edit_adjustment::is_adjustment;
58	use crate::edit_paste::{absorb_media, parse_payload};
59	use crate::lut::{look_media_ids, remap_look_media};
60	use crate::model::{Clip, GraphicProps, Project, Qualifier, ShapeProps, Source, TextProps};
61	use crate::model_graphic::{check_count, check_props};
62	use crate::outcome::Outcome;
63	use crate::patch::{Group, GROUPS};
64	use crate::video_gate::{hide_silent_media, remap_hide_silent};
65	
66	/// The five groups `paste_attributes` takes by name — `video | audio | text
67	/// | shape | graphic` on the wire. The first four are the PATCH groups
68	/// ([`Group`]); `graphic` is the paste's alone (module doc).
69	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
70	#[serde(rename_all = "snake_case")]
71	pub enum PasteGroup {
72	    Video,
73	    Audio,
74	    Text,
75	    Shape,
76	    Graphic,
77	}
78	
79	impl PasteGroup {
80	    /// The wire name, which is the patch group's own for the first four.
81	    pub(crate) fn name(self) -> &'static str {
82	        match self.layer() {
83	            Some(layer) => layer.name(),
84	            None => "graphic",
85	        }
86	    }
87	
88	    /// The patch group this names, or `None` for `graphic`, which is not a
89	    /// group of the layer.
90	    fn layer(self) -> Option<Group> {
91	        match self {
92	            PasteGroup::Video => Some(Group::Video),
93	            PasteGroup::Audio => Some(Group::Audio),
94	            PasteGroup::Text => Some(Group::Text),
95	            PasteGroup::Shape => Some(Group::Shape),
96	            PasteGroup::Graphic => None,
97	        }
98	    }
99	
100	    /// The same group as a name a caller could have sent.
101	    fn of(layer: Group) -> PasteGroup {
102	        match layer {
103	            Group::Video => PasteGroup::Video,
104	            Group::Audio => PasteGroup::Audio,
105	            Group::Text => PasteGroup::Text,
106	            Group::Shape => PasteGroup::Shape,
107	        }
108	    }
109	}
110	
111	/// Whether a clip HAS the group — the model's only notion of what a clip
112	/// can take, the same one `edit_props.rs`'s patches go by.
113	fn has_group(clip: &Clip, group: Group) -> bool {
114	    match group {
115	        Group::Video => clip.video.is_some(),
116	        Group::Audio => clip.audio.is_some(),
117	        Group::Text => clip.text.is_some(),
118	        Group::Shape => clip.shape.is_some(),
119	    }
120	}
121	
122	/// What a graphic clip is drawn from, or `None` for a clip that is not one
123	/// — `set_graphic`'s test: the source AND the description.
124	fn graphic_of(clip: &Clip) -> Option<&GraphicProps> {
125	    match clip.source {
126	        Source::Graphic => clip.graphic.as_ref(),
127	        _ => None,
128	    }
129	}
130	
131	/// Whether a clip has a group a caller can name.
132	fn has(clip: &Clip, group: PasteGroup) -> bool {
133	    match group.layer() {
134	        Some(layer) => has_group(clip, layer),
135	        None => graphic_of(clip).is_some(),
136	    }
137	}
138	
139	/// The copied props as they may be stored: shape-checked with no schema,
140	/// `null`s dropped, counted (G-32 (f)). The sentences are
141	/// `model_graphic.rs`'s own.
142	fn checked_props(from: &GraphicProps) -> Result<Map<String, Value>, String> {
143	    let mut stored = check_props(&from.props, None)?;
144	    stored.retain(|_, value| !value.is_null());
145	    check_count(&stored)?;
146	    Ok(stored)
147	}
148	
149	/// Makes `into` hold exactly `props` plus the keys in `keep`: a key that
150	/// neither `props` nor `keep` holds is removed with `shift_remove`, a key
151	/// both maps have keeps its slot, a kept key keeps its slot and value, and
152	/// a new key is appended in `props`' order.
153	fn replace_props(into: &mut Map<String, Value>, props: &Map<String, Value>, keep: &[String]) {
154	    let gone: Vec<String> = into
155	        .keys()
156	        .filter(|key| !props.contains_key(*key) && !keep.contains(*key))
157	        .cloned()
158	        .collect();
159	    for key in gone {
160	        into.shift_remove(&key);
161	    }
162	    for (key, value) in props {
163	        into.insert(key.clone(), value.clone());
164	    }
165	}
166	
167	/// Replaces `target`'s group with a copy of `source`'s, keeping the fields
168	/// that make the target the clip it is (module doc). A side that lacks the
169	/// group leaves the target as it was — the caller has already refused that
170	/// case by name, so this is only the shape that cannot invent a group.
171	fn copy_group(target: &mut Clip, source: &Clip, group: Group) {
172	    match group {
173	        Group::Video => {
174	            let picture_target = !is_adjustment(target);
175	            let picture_source = !is_adjustment(source);
176	            if let (Some(into), Some(from)) = (target.video.as_mut(), &source.video) {
177	                let own = into.qualifier;
178	                *into = from.clone();
179	                // The qualifier follows the clip kind (module doc, GR-13).
180	                if picture_target {
181	                    into.qualifier = Qualifier::default();
182	                } else if picture_source {
183	                    into.qualifier = own;
184	                }
185	            }
186	        }
187	        Group::Audio => {
188	            if let (Some(into), Some(from)) = (target.audio.as_mut(), &source.audio) {
189	                *into = *from;
190	            }
191	        }
192	        Group::Text => {
193	            if let (Some(into), Some(from)) = (target.text.as_mut(), &source.text) {
194	                let content = std::mem::take(&mut into.content);
195	                let words = std::mem::take(&mut into.words);
196	                *into = TextProps {
197	                    content,
198	                    words,
199	                    ..from.clone()
200	                };
201	            }
202	        }
203	        Group::Shape => {
204	            if let (Some(into), Some(from)) = (target.shape.as_mut(), &source.shape) {
205	                *into = ShapeProps {
206	                    kind: into.kind,
207	                    width: into.width,
208	                    height: into.height,
209	                    from: into.from,
210	                    to: into.to,
211	                    ..from.clone()
212	                };
213	            }
214	        }
215	    }
216	}
217	
218	impl Project {
219	    /// Copies one payload clip's property groups onto every named clip (spec
220	    /// §6) — Edit ▸ Paste Attributes. The clip is the EARLIEST, then the
221	    /// front-most (`track` is a depth, 0 = front), then the lower id: Copy
222	    /// writes a selection in storage — creation — order, not the timeline's,
223	    /// so the array's first is a clip the user cannot see. Which fields
224	    /// travel, which a target keeps and why a group is replaced rather than
225	    /// merged are the module doc's.
226	    ///
227	    /// `groups` absent means every one of the four LAYER groups both sides
228	    /// have, silently skipping the rest: video onto a text clip from a media
229	    /// clip copies the video, leaves the text alone and drops the audio,
230	    /// which has nowhere to go. `graphic` is never in that set, and
231	    /// `skip_missing` changes nothing there. A NAMED group is different —
232	    /// one the source lacks is an `Err` naming the group, one a target lacks
233	    /// is `Err("clip N has no audio properties")`, the patches' answer, and
234	    /// `graphic` onto a clip drawn by another module is an `Err` naming both
235	    /// modules — because a caller who asked for it would otherwise never
236	    /// learn it did not happen. With `skip_missing` a caller says it does
237	    /// not need to: a named group the source lacks is dropped and a target
238	    /// that cannot take one is skipped for it (G-32). An empty explicit
239	    /// list, an identity paste and an empty selection are all identities.
240	    /// The copied layer groups then pass the range checks a patch does, so a
241	    /// payload written by hand cannot smuggle in a value the inspector would
242	    /// refuse; copied graphic props pass the shape check, the first time a
243	    /// target takes them.
244	    pub fn paste_attributes(
245	        &self,
246	        clips: &[u32],
247	        payload: &Value,
248	        groups: Option<&[PasteGroup]>,
249	        skip_missing: bool,
250	    ) -> Result<Outcome, String> {
251	        let payload = parse_payload(payload)?;
252	        let earliest = |c: &&Clip| (c.start, c.track, c.id);
253	        let Some(source) = payload.clips.iter().min_by_key(earliest) else {
254	            return Err("paste payload has no clips".to_string());
255	        };
256	        let mut named: Option<Vec<PasteGroup>> = None;
257	        if let Some(asked) = groups {
258	            let mut kept = Vec::new();
259	            for group in asked {
260	                if has(source, *group) {
261	                    kept.push(*group);
262	                } else if !skip_missing {
263	                    return Err(format!("payload clip has no {} properties", group.name()));
264	                }
265	            }
266	            named = Some(kept);
267	        }
268	        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();
269	
270	        let mut next = self.clone();
271	        // Read at most once, by the first target that takes it (G-32 (f)).
272	        let mut copied: Option<Map<String, Value>> = None;
273	        // The source with its looks pointing at THIS project's LUTs, made by
274	        // the first target that takes the video group (spec §11 GR-8): the
275	        // LUTs it names are absorbed by path, as `paste` absorbs media, and
276	        // an id the payload lacks becomes no look.
277	        let mut looked: Option<Clip> = None;
278	        for id in ids {
279	            let Some(mut target) = next.clip(id).cloned() else {
280	                continue;
281	            };
282	            let chosen: Vec<PasteGroup> = match &named {
283	                Some(named) => named.clone(),
284	                None => GROUPS
285	                    .into_iter()
286	                    .filter(|g| has_group(source, *g) && has_group(&target, *g))
287	                    .map(PasteGroup::of)
288	                    .collect(),
289	            };
290	            let takes_video = chosen.contains(&PasteGroup::Video) && target.video.is_some();
291	            if takes_video && looked.is_none() {
292	                let looks = [
293	                    look_media_ids(source),
294	                    hide_silent_media(source).into_iter().collect(),
295	                ];
296	                let map = absorb_media(&mut next, &payload, &[], &looks.concat())?;
297	                let mut copy = source.clone();
298	                remap_look_media(&mut copy, &map);
299	                remap_hide_silent(&mut copy, &map);
300	                looked = Some(copy);
301	            }
302	            let from = looked.as_ref().unwrap_or(source);
303	            for group in chosen {
304	                if !has(&target, group) {
305	                    if skip_missing {
306	                        continue;
307	                    }
308	                    return Err(format!("clip {id} has no {} properties", group.name()));
309	                }
310	                let Some(layer) = group.layer() else {
311	                    let keep: Vec<String> = target.graphic.as_ref().map_or_else(Vec::new, |g| {
312	                        let named = g.props.keys().filter(|key| names_prop(&target, key));
313	                        named.cloned().collect()
314	                    });
315	                    let (Some(from), Some(into)) = (graphic_of(from), target.graphic.as_mut())
316	                    else {
317	                        continue;
318	                    };
319	                    if into.name != from.name {
320	                        if skip_missing {
321	                            continue;
322	                        }
323	                        return Err(format!(
324	                            "clip {id} is drawn by \"{}\" and the payload clip by \"{}\"; \
325	                             graphic props are pasted only between clips of one module",
326	                            into.name, from.name
327	                        ));
328	                    }
329	                    if copied.is_none() {
330	                        copied = Some(checked_props(from)?);
331	                    }
332	                    if let Some(props) = &copied {
333	                        replace_props(&mut into.props, props, &keep);
334	                    }
335	                    continue;
336	                };
337	                copy_group(&mut target, from, layer);
338	                next.normalise_and_check_group(&mut target, layer)?;
339	            }
340	            if let Some(slot) = next.clip_mut(id) {
341	                *slot = target;
342	            }
343	        }
344	        self.finish(next)
345	    }
346	}
347	//! `paste` — the clipboard's half of Cut / Copy / Paste (spec §6, table
348	//! "Clips").
349	//!
350	//! Its own module because pasting is a different concern from every other
351	//! placement op: the material does not come from the project. A `move_clip`
352	//! or a `duplicate` rearranges clips the project already owns, so the ids,
353	//! the media and the tracks all exist; a paste arrives as JSON that may have
354	//! been written by ANOTHER document — a different id space, a different
355	//! media list, a different frame grid, possibly a different canvas — and has
356	//! to be made to fit before a single clip lands.
357	//!
358	//! ### The payload
359	//!
360	//! ```json
361	//! {"clips": [ …the §5.2 clip objects… ], "media": [ …the §5.2 media rows… ],
362	//!  "nests": [ …the §5.2 nest objects the clips show… ]}
363	//! ```
364	//!
365	//! It is exactly what `EditorViewController+Clipboard.swift` puts on
366	//! `NSPasteboard.general` under `com.kgalligan.framejob.clips`: the clips
367	//! copied verbatim out of the source document's own `project.json`, plus the
368	//! media rows those clips name and any nest they show. Four things about it
369	//! are worth stating before the code:
370	//!
371	//! 1. **A payload clip's `track` is a DEPTH, not an id** — 0 is the
372	//!    front-most track the copy covered, 1 the one behind it, and so on. A
373	//!    track id from another document means nothing here, and the depth is
374	//!    the only thing about the source's track stack worth carrying: it is
375	//!    what makes a two-lane selection paste back onto two lanes.
376	//! 2. **Ids are re-minted, always.** Clips, actions, any media row the
377	//!    project does not already have, and every nest — with its tracks, its
378	//!    clips and their actions — get fresh ids from `next_id`, so a payload
379	//!    can be pasted repeatedly and into the document it came from.
380	//! 3. **A nest is COPIED, never matched.** Media is matched by path because
381	//!    it names a file two documents can share; a nest is content, and two
382	//!    nests that look alike are no more the same object than two clips are.
383	//!    So every paste of a nest clip brings its own copy, and editing one
384	//!    afterwards leaves the other alone.
385	//! 4. **Unknown keys are ignored**, deliberately: no `deny_unknown_fields`
386	//!    here. The payload is machine-written, a future build will add keys to
387	//!    it, and refusing a whole paste over a key this build has not learned
388	//!    yet would be worse than dropping it — the same reasoning `model.rs`
389	//!    gives for the project schema itself.
390	//!
391	//! ### Making it fit
392	//!
393	//! Every project time is re-snapped to THIS document's frame grid
394	//! ([`Project::snapped`]), because the payload may come from a document at
395	//! another rate; source times are not, for the same reason `trim_start` and
396	//! `split` do not snap them — an `in` point is measured on the media's grid,
397	//! not the canvas's. Media is matched to the existing `media[]` **by path**,
398	//! which is `add_media`'s one-entry-per-path rule, so pasting between two
399	//! documents that both reference `/m/talk.mov` reuses the row that is there
400	//! and pasting into a document that has never seen it brings the row along;
401	//! a row brought along first passes `add_media`'s field checks, with its
402	//! `original` stored as `add_media` stores it, and a row matched by path is
403	//! the project's own and is not checked. Every group of every clip that
404	//! lands, nested ones included, first passes the patch path's
405	//! normalise-and-check, as `paste_attributes`' do — a video group
406	//! `set_video`'s own chain, `Project::settle_video`.
407	//!
408	//! Placement obeys the overlap rule like everything else (spec §11), and a
409	//! clip the rule refuses on its target track goes on a NEW track in front —
410	//! the same fallback `EditorViewController+AddClips.swift` uses for Add
411	//! Text, and for the same reason: a paste at a busy playhead should land
412	//! somewhere visible rather than beep. That fallback is why the only
413	//! "changes nothing" answer here is an empty clip list.
414	//!
415	//! `paste_attributes` reads the same payload and places nothing; it is
416	//! `edit_paste_attributes.rs`'s, which parses the payload through
417	//! [`parse_payload`].
418	
419	use std::collections::HashMap;
420	
421	use serde::Deserialize;
422	use serde_json::Value;
423	
424	use crate::edit_commit::Landing;
425	use crate::edit_link::relink_copies;
426	use crate::edit_track::{check_media_fields, normalize_original};
427	use crate::export::describe;
428	use crate::format::MAX_TRACKS;
429	use crate::lut::{look_media_ids, remap_look_media};
430	use crate::model::{Clip, Media, Nest, Project, Source};
431	use crate::outcome::Outcome;
432	use crate::time::Ticks;
433	use crate::video_gate::{hide_silent_media, remap_hide_silent};
434	
435	/// One clipboard payload. `media` and `nests` default because most
436	/// selections name neither; `clips` deliberately does not, so a payload that
437	/// forgot the key is an error naming it rather than a silent no-op.
438	#[derive(Debug, Deserialize)]
439	pub(crate) struct Payload {
440	    pub(crate) clips: Vec<Clip>,
441	    #[serde(default)]
442	    pub(crate) media: Vec<Media>,
443	    #[serde(default)]
444	    pub(crate) nests: Vec<Nest>,
445	}
446	
447	/// The nest a source shows, or `None` for every other kind.
448	fn source_nest(source: &Source) -> Option<u32> {
449	    match source {
450	        Source::Nest { project } => Some(*project),
451	        _ => None,
452	    }
453	}
454	
455	/// The same source pointing at this project's media and nest ids.
456	///
457	/// An id neither map carries is impossible — [`absorb_media`] and
458	/// [`absorb_nests`] resolve every one the clips name before this runs — but
459	/// ids are passed through rather than unwrapped, so a future caller that
460	/// skipped a step gets `validate`'s "refers to unknown media" or "refers to
461	/// unknown nest" instead of a panic.
462	fn remap_source(source: &Source, media: &HashMap<u32, u32>, nests: &HashMap<u32, u32>) -> Source {
463	    let mapped = |id: &u32| media.get(id).copied().unwrap_or(*id);
464	    match source {
465	        Source::Media {
466	            media: id,
467	            r#in,
468	            reversed,
469	        } => Source::Media {
470	            media: mapped(id),
471	            r#in: (*r#in).max(0),
472	            reversed: *reversed,
473	        },
474	        Source::Still { media: id, at } => Source::Still {
475	            media: mapped(id),
476	            at: (*at).max(0),
477	        },
478	        Source::Image { media: id } => Source::Image { media: mapped(id) },
479	        Source::Nest { project } => Source::Nest {
480	            project: nests.get(project).copied().unwrap_or(*project),
481	        },
482	        other => other.clone(),
483	    }
484	}
485	
486	/// The payload nests the pasted clips show, directly or through one
487	/// another, in the order they are discovered.
488	///
489	/// The traversal is the same shape `validate`'s cycle check uses: an id is
490	/// queued once, so a payload whose nests point at each other terminates here
491	/// and is refused later by `validate`, where the message about a cycle
492	/// already lives.
493	///
494	/// `Err` when a clip shows a nest the payload does not carry — a truncated
495	/// or hand-written payload, whose clip would otherwise become a dangling
496	/// reference.
497	fn reachable_nests(payload: &Payload) -> Result<Vec<&Nest>, String> {
498	    let mut wanted: Vec<u32> = Vec::new();
499	    for clip in &payload.clips {
500	        if let Some(id) = source_nest(&clip.source) {
501	            if !wanted.contains(&id) {
502	                wanted.push(id);
503	            }
504	        }
505	    }
506	    let mut found: Vec<&Nest> = Vec::new();
507	    let mut index = 0;
508	    while let Some(id) = wanted.get(index).copied() {
509	        index += 1;
510	        let Some(nest) = payload.nests.iter().find(|n| n.id == id) else {
511	            return Err(format!(
512	                "a pasted clip shows nest {id}, which the payload does not carry"
513	            ));
514	        };
515	        found.push(nest);
516	        for child in nest.child_nests() {
517	            if !wanted.contains(&child) {
518	                wanted.push(child);
519	            }
520	        }
521	    }
522	    Ok(found)
523	}
524	
525	/// Copies every reachable payload nest into the project with fresh ids
526	/// throughout — the nest, its tracks, its clips and their actions — and
527	/// returns the payload-id → project-id map.
528	///
529	/// Every nest gets its new id BEFORE any is rewritten, so a nest showing
530	/// another nest is remapped whichever order the two were discovered in.
531	/// Times inside are re-snapped to this document's frame grid for the same
532	/// reason the pasted clips' are: the payload may come from a document at
533	/// another rate, and nothing sub-frame may reach the model.
534	///
535	/// `Err` when a clip inside fails [`Project::normalise_and_check_pasted`].
536	/// That runs in a second pass, once every copy is in, so a clip showing a
537	/// nest is measured against the copy it shows.
538	fn absorb_nests(
539	    project: &mut Project,
540	    nests: &[&Nest],
541	    media: &HashMap<u32, u32>,
542	) -> Result<HashMap<u32, u32>, String> {
543	    let mut map: HashMap<u32, u32> = HashMap::new();
544	    for nest in nests {
545	        map.insert(nest.id, project.allocate_id());
546	    }
547	    let first = project.nests.len();
548	    for nest in nests {
549	        let mut copy = (*nest).clone();
550	        copy.id = map.get(&nest.id).copied().unwrap_or(nest.id);
551	        let mut tracks: HashMap<u32, u32> = HashMap::new();
552	        for track in copy.tracks.iter_mut() {
553	            let id = project.allocate_id();
554	            tracks.insert(track.id, id);
555	            track.id = id;
556	        }
557	        let mut fresh: HashMap<u32, u32> = HashMap::new();
558	        for clip in copy.clips.iter_mut() {
559	            let old = clip.id;
560	            project.remint(clip);
561	            fresh.insert(old, clip.id);
562	            clip.track = tracks.get(&clip.track).copied().unwrap_or(clip.track);
563	            clip.source = remap_source(&clip.source, media, &map);
564	            remap_look_media(clip, media);
565	            remap_hide_silent(clip, media);
566	            // The speed BEFORE the duration: the bound is measured at it.
567	            if !(clip.speed.is_finite() && clip.speed > 0.0) {
568	                clip.speed = 1.0;
569	            }
570	        }
571	        // A copied pair re-pairs through the fresh ids (spec §11 AU-96).
572	        relink_copies(&mut copy.clips, &fresh);
573	        project.nests.push(copy);
574	    }
575	    for (offset, nest) in nests.iter().enumerate() {
576	        let index = first + offset;
577	        let Some(mut clips) = project.nests.get(index).map(|n| n.clips.clone()) else {
578	            continue;
579	        };
580	        for (clip, source) in clips.iter_mut().zip(&nest.clips) {
581	            project.normalise_and_check_pasted(clip, source.id)?;
582	            project.resnap_clip_times(clip);
583	        }
584	        if let Some(copy) = project.nests.get_mut(index) {
585	            copy.clips = clips;
586	        }
587	    }
588	    Ok(map)
589	}
