591	/// Resolves every media the pasted clips name onto an entry of this
592	/// project's `media[]`, appending the ones that are not there, and returns
593	/// the payload-id → project-id map.
594	///
595	/// `sources` are the media the landing clips SHOW and `looks` the LUTs their
596	/// looks name ([`wanted_media`]) — the payload's own clips AND those inside
597	/// the nests they show, which reference the payload's `media[]` in the same
598	/// one id space (spec §5.2) and would otherwise dangle.
599	///
600	/// Only media a pasted clip actually shows or looks through is brought
601	/// across. The pasteboard writer only ever puts those there, and a payload
602	/// row nothing references would arrive as a Media-tab entry the user did not
603	/// ask for and cannot account for.
604	///
605	/// `Err` when a clip shows a media the payload does not carry (a truncated
606	/// or hand-written payload — the clip would otherwise become a dangling
607	/// reference `validate` refuses), when a row's path is empty, or when a row
608	/// about to be APPENDED fails `add_media`'s field checks
609	/// (`edit_track.rs`'s `check_media_fields`, on the row with its `original`
610	/// stored as `add_media` stores it; `pasted media N: …`, N the payload's
611	/// id). A row matched by path is the project's own and is not checked. A
612	/// look's id the payload lacks is skipped (spec §11 GR-8).
613	///
614	/// A row APPENDED here keeps its Camera Log (spec §11 GR-16) with its
615	/// `color.lut` pointed at this project's id for that LUT, or loses its
616	/// `color` when the LUT did not come with it; a row matched by path keeps
617	/// its own.
618	pub(crate) fn absorb_media(
619	    project: &mut Project,
620	    payload: &Payload,
621	    sources: &[u32],
622	    looks: &[u32],
623	) -> Result<HashMap<u32, u32>, String> {
624	    let mut map: HashMap<u32, u32> = HashMap::new();
625	    let mut appended: Vec<u32> = Vec::new();
626	    for (id, shown) in sources
627	        .iter()
628	        .map(|id| (*id, true))
629	        .chain(looks.iter().map(|id| (*id, false)))
630	    {
631	        if map.contains_key(&id) {
632	            continue;
633	        }
634	        let Some(entry) = payload.media.iter().find(|m| m.id == id) else {
635	            if shown {
636	                return Err(format!(
637	                    "a pasted clip shows media {id}, which the payload does not carry"
638	                ));
639	            }
640	            // A look's LUT the payload lacks (an end may name one that is
641	            // gone, spec §11 GR-8): left out of the map, so
642	            // `remap_look_media` makes it no look.
643	            continue;
644	        };
645	        let path = entry.path.trim().to_string();
646	        if path.is_empty() {
647	            return Err("a pasted media path must not be empty".to_string());
648	        }
649	        let local = match project.media.iter().find(|m| m.path == path) {
650	            Some(found) => found.id,
651	            None => {
652	                let mut record = entry.clone();
653	                record.path = path;
654	                // An empty bookmark is not a bookmark — `add_media`'s rule.
655	                record.bookmark = record.bookmark.filter(|b| !b.trim().is_empty());
656	                // `add_media`'s own field checks, on the row as it would be
657	                // stored (issue #349), before it takes an id.
658	                record.original = normalize_original(record.original);
659	                check_media_fields(&record).map_err(|why| format!("pasted media {id}: {why}"))?;
660	                record.id = project.allocate_id();
661	                let new_id = record.id;
662	                project.media.push(record);
663	                appended.push(new_id);
664	                new_id
665	            }
666	        };
667	        map.insert(id, local);
668	    }
669	    for row in project.media.iter_mut() {
670	        if !appended.contains(&row.id) {
671	            continue;
672	        }
673	        if let Some(lut) = row.color.and_then(|color| color.lut) {
674	            match map.get(&lut) {
675	                Some(local) => {
676	                    if let Some(color) = row.color.as_mut() {
677	                        color.lut = Some(*local);
678	                    }
679	                }
680	                None => row.color = row.color.and_then(|color| color.without_camera_log()),
681	            }
682	        }
683	    }
684	    Ok(map)
685	}
