687	/// The ids `absorb_media` resolves for `clips`, in the order they name
688	/// them (a `Vec` rather than a set, so the new rows are appended and
689	/// numbered reproducibly): the media each SHOWS, then the LUTs their looks
690	/// name (spec §11 GR-8) and the LUT each shown media's payload row converts
691	/// with (`color.lut`, GR-16).
692	fn wanted_media(clips: &[&Clip], payload: &Payload) -> (Vec<u32>, Vec<u32>) {
693	    let mut sources: Vec<u32> = Vec::new();
694	    let mut looks: Vec<u32> = Vec::new();
695	    for clip in clips {
696	        if let Some(id) = clip.source.media() {
697	            if !sources.contains(&id) {
698	                sources.push(id);
699	            }
700	        }
701	        for id in look_media_ids(clip)
702	            .into_iter()
703	            .chain(hide_silent_media(clip))
704	        {
705	            if !looks.contains(&id) {
706	                looks.push(id);
707	            }
708	        }
709	    }
710	    let converting = sources.iter().filter_map(|id| {
711	        let row = payload.media.iter().find(|m| m.id == *id)?;
712	        row.color?.lut
713	    });
714	    for id in converting.collect::<Vec<u32>>() {
715	        if !looks.contains(&id) {
716	            looks.push(id);
717	        }
718	    }
719	    (sources, looks)
720	}
