909	    /// The `paste` payload for the current selection: the selected clips
910	    /// verbatim out of `project.json` with each clip's `track` rewritten to
911	    /// its depth from the front, plus the media rows those clips name.
912	    ///
913	    /// nil when the project JSON cannot be read or the selection resolved to
914	    /// no clips at all — both of which mean there is nothing to put on the
915	    /// pasteboard, and the caller beeps.
916	    private func clipboardPayload(for document: ProjectDocument) -> [String: Any]? {
917	        // The EDITED project (road map 2's phase 9). Inside a nest the
918	        // selected clips are the NEST's, and they are the top level of this
919	        // JSON — so a Copy in a nest copies what was picked, and the `track`
920	        // depths it rewrites are counted against the nest's own stack, which
921	        // is what the paste on the other side will be measured against.
922	        guard let data = document.editedProject.json.data(using: .utf8),
923	              let root = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
924	              let clips = root["clips"] as? [[String: Any]]
925	        else { return nil }
926	        let snapshot = document.editedProject.snapshot
927	        let front = snapshot.tracks.count - 1
928	        // A selected PICTURE half brings its linked sound, so a pasted
929	        // detached clip lands as a pair; a selected sound half is copied
930	        // alone, and the core clears its link on paste (spec §11 AU-96).
931	        var selection = document.selection
932	        for id in document.selection {
933	            if let clip = snapshot.clip(id), clip.enabled.video, let partner = clip.linked {
934	                selection.insert(partner)
935	            }
936	        }
937	
938	        var payloadClips: [[String: Any]] = []
939	        var wanted: Set<UInt32> = []
940	        for clip in clips {
941	            guard let id = (clip["id"] as? NSNumber)?.uint32Value, selection.contains(id),
942	                  let track = (clip["track"] as? NSNumber)?.uint32Value,
943	                  let index = snapshot.trackIndex(of: track)
944	            else { continue }
945	            var copied = clip
946	            copied["track"] = front - index
947	            payloadClips.append(copied)
948	            wanted.formUnion(Self.payloadMediaIDs(clip))
949	        }
950	        guard !payloadClips.isEmpty else { return nil }
951	        // A wanted row's Camera Log LUT travels with it (spec §11 GR-16), so
952	        // the paste lands the conversion remapped rather than dropping it.
953	        for id in wanted {
954	            if let lut = snapshot.media(id)?.color?.lut { wanted.insert(lut) }
955	        }
956	
957	        // Only the rows the copied clips SHOW or look through, and the LUTs
958	        // those convert with: a media entry nothing points at would arrive in
959	        // the other document as a Media-tab row the user cannot account for.
960	        let media = (root["media"] as? [[String: Any]] ?? []).filter { entry in
961	            guard let id = (entry["id"] as? NSNumber)?.uint32Value else { return false }
962	            return wanted.contains(id)
963	        }
964	        return ["clips": payloadClips, "media": media]
965	    }
966	
967	    /// The media ids one copied clip (its `project.json` object) names: its
968	    /// source's, its base look's, its gate's (`video.hide_silent.media`, spec
969	    /// §11 CO-92) and each action end's look's (spec §11 GR-8), in that order
970	    /// without repeats — the rows a paste into another project needs. An end
971	    /// may name a LUT that is gone; its row is simply not found.
972	    static func payloadMediaIDs(_ clip: [String: Any]) -> [UInt32] {
973	        func lookMedia(_ video: Any?) -> UInt32? {
974	            guard let video = video as? [String: Any], let look = video["look"] as? [String: Any]
975	            else { return nil }
976	            return (look["media"] as? NSNumber)?.uint32Value
977	        }
978	        var found: [UInt32?] = [
979	            ((clip["source"] as? [String: Any])?["media"] as? NSNumber)?.uint32Value,
980	            lookMedia(clip["video"]),
981	            (((clip["video"] as? [String: Any])?["hide_silent"] as? [String: Any])?["media"]
982	                as? NSNumber)?.uint32Value,
983	        ]
984	        for action in clip["actions"] as? [[String: Any]] ?? [] {
985	            found.append(lookMedia((action["end"] as? [String: Any])?["video"]))
986	        }
987	        var ids: [UInt32] = []
988	        for id in found.compactMap({ $0 }) where !ids.contains(id) { ids.append(id) }
989	        return ids
990	    }
