992	    /// The plain-text fallback: what was copied and the span it covered, in
993	    /// the document's own timecode (`ReelTime.format`, as everywhere else).
994	    private func clipboardSummary(for document: ProjectDocument) -> String {
995	        let clips = selectedClips
996	        let canvas = document.editedProject.snapshot.canvas
997	        let frames = canvas.timecodeFrames
998	        let start = clips.first?.start ?? 0
999	        let end = clips.map { $0.end }.max() ?? start
1000	        let count = clips.count == 1 ? "1 clip" : "\(clips.count) clips"
1001	        return "Frame Job — \(count), "
1002	            + ReelTime.format(start, fps: canvas.fps, frames: frames) + " to "
1003	            + ReelTime.format(end, fps: canvas.fps, frames: frames)
1004	    }
