1038	    // MARK: - Paste Attributes
1039	
1040	    /// ⌥⌘V. The payload's EARLIEST clip's LOOK — its video, audio, text and
1041	    /// shape groups, the earliest by start, then the front-most track, then
1042	    /// the lower id — onto every selected clip, leaving `groups` to the core's
1043	    /// default (every group both sides have, spec §6). Nothing that makes the
1044	    /// clip THIS clip travels: not its place, speed, actions, transition, name
1045	    /// or label, and not a text clip's words or a shape's geometry.
1046	    ///
1047	    /// Whole selection, one op, one undo step. An IDENTITY — the payload's
1048	    /// clip and the targets share no group, or the look is already theirs —
1049	    /// is `applyEdit`'s beep, and an out-of-range payload is its error,
1050	    /// presented. There is no group picker here: the default rule is what
1051	    /// ⌥⌘V has always meant in a cutting room, and the agent's tool
1052	    /// (`paste_attributes`) takes `groups` for anyone who needs the choice.
1053	    func pasteAttributes(from pasteboard: NSPasteboard = .general) {
1054	        guard let document = document, !document.selection.isEmpty,
1055	              let payload = pasteboardPayload(on: pasteboard)
1056	        else {
1057	            NSSound.beep()
1058	            return
1059	        }
1060	        document.applyEdit(
1061	            "Paste Attributes",
1062	            .pasteAttributes(clips: Array(document.selection), payload: payload))
1063	    }
1064	
1065	    // MARK: - Paste Graphic Properties
1066	
1067	    /// Edit ▸ Paste Graphic Properties (spec §11 G-32), which has no key. A
1068	    /// menu sends its `NSMenuItem`, so the app reads the general pasteboard;
1069	    /// a probe sends this action a private pasteboard as its sender, which
1070	    /// is how the line below is measured and not only typechecked.
1071	    @objc func pasteGraphicProperties(_ sender: Any?) {
1072	        pasteGraphicProps(from: sender as? NSPasteboard ?? .general)
1073	    }
1074	
1075	    /// The copied graphic's props — all of them, its words included — onto
1076	    /// every selected clip drawn by the SAME graphic; each keeps its own
1077	    /// size, in point and length. ONE op, and nothing about the payload is
1078	    /// read here: `groups: ["graphic"]` names the group ⌥⌘V never carries,
1079	    /// and `skipMissing` makes the core skip a selected clip that cannot take
1080	    /// it rather than refuse the paste. So when the copied clip is not a
1081	    /// graphic, or no selected clip is drawn by the same one, the answer is
1082	    /// an identity — `applyEdit`'s beep — and copied props the core will not
1083	    /// store, onto a clip that takes them, are its sentence in an alert.
1084	    func pasteGraphicProps(from pasteboard: NSPasteboard = .general) {
1085	        guard let document = document, !document.selection.isEmpty,
1086	              let payload = pasteboardPayload(on: pasteboard)
1087	        else {
1088	            NSSound.beep()
1089	            return
1090	        }
1091	        document.applyEdit(
1092	            "Paste Graphic Properties",
1093	            .pasteAttributes(
1094	                clips: Array(document.selection), payload: payload,
1095	                groups: ["graphic"], skipMissing: true))
1096	    }
1097	
1098	    /// The payload on the pasteboard, or nil when there is nothing of ours
1099	    /// there to paste — an empty pasteboard, another app's content, or a
1100	    /// payload with no clips in it.
1101	    private func pasteboardPayload(on pasteboard: NSPasteboard = .general) -> [String: Any]? {
1102	        guard let data = pasteboard.data(forType: Self.clipsPasteboardType),
1103	              let payload = try? JSONSerialization.jsonObject(with: data) as? [String: Any],
1104	              let clips = payload["clips"] as? [Any], !clips.isEmpty
1105	        else { return nil }
1106	        return payload
1107	    }
1108	
1109	    /// Whether ⌘V has anything to do. Only the TYPE is inspected, not the
1110	    /// bytes: this runs on every menu validation, and reading a pasteboard's
1111	    /// available types is cheap where decoding its data is not.
1112	    func canPasteClips(on pasteboard: NSPasteboard = .general) -> Bool {
1113	        pasteboard.availableType(from: [Self.clipsPasteboardType]) != nil
1114	    }
1115	
1116	    // MARK: - Validation
1117	
1118	    /// The half of `validateUserInterfaceItem` this file owns. nil means "not
1119	    /// mine" and leaves the base file's answer alone.
1120	    func validateClipboardAction(
1121	        _ action: Selector, pasteboard: NSPasteboard = .general
1122	    ) -> Bool? {
1123	        guard let document = document else { return false }
1124	        switch action {
1125	        case #selector(cut(_:)), #selector(copy(_:)):
1126	            return !document.selection.isEmpty
1127	        case #selector(paste(_:)):
1128	            return canPasteClips(on: pasteboard)
1129	        case #selector(pasteAttributes(_:)):
1130	            // Paste needs no selection (the clips land at the playhead);
1131	            // Paste Attributes needs something to paste ONTO.
1132	            return canPasteClips(on: pasteboard) && !document.selection.isEmpty
1133	        case #selector(pasteGraphicProperties(_:)):
1134	            // Something of ours to read and a graphic to paste onto. WHAT was
1135	            // copied is not read here (the bytes, on every menu validation):
1136	            // a copied clip that is not a graphic is the item's beep (G-32).
1137	            return canPasteClips(on: pasteboard)
1138	                && selectedClips.contains { $0.source == .graphic && $0.graphic != nil }
1139	        default:
1140	            return nil
1141	        }
1142	    }
1143	}
