435	/// One clipboard payload. `media` and `nests` default because most
436	/// selections name neither; `clips` deliberately does not, so a payload that
437	/// forgot the key is an error naming it rather than a silent no-op.
438	#[derive(Debug, Deserialize)]
439	pub(crate) struct Payload {
440	    pub(crate) clips: Vec<Clip>,
441	    #[serde(default)]
442	    pub(crate) media: Vec<Media>,
443	    #[serde(default)]
444	    pub(crate) nests: Vec<Nest>,
445	}
