722	/// Parses the payload, naming what was wrong.
723	pub(crate) fn parse_payload(payload: &Value) -> Result<Payload, String> {
724	    if !payload.is_object() {
725	        return Err(format!(
726	            "a paste payload must be a json object, not {}",
727	            describe(payload)
728	        ));
729	    }
730	    serde_json::from_value(payload.clone())
731	        .map_err(|e| format!("paste payload does not match the schema: {e}"))
732	}
