734	impl Project {
735	    /// Inserts a clipboard payload's clips with fresh ids, the earliest one
736	    /// landing exactly at `at` and the rest keeping their offsets from it
737	    /// (spec §6).
738	    ///
739	    /// `track` names where the payload's front-most depth lands and retargets
740	    /// the rest by the same index delta, the way `move_clip` does; absent, it
741	    /// is the front-most track, so a paste keeps the copy's own layering.
742	    /// Tracks missing BEHIND the destination are added; a clip the overlap
743	    /// rule refuses on its target track goes on a new track in front.
744	    ///
745	    /// An identity for an empty clip list — the only answer that changes
746	    /// nothing, since the fallback track means a placement cannot fail.
747	    /// `Err` for a malformed payload, an unknown `track`, a clip naming a
748	    /// media the payload does not carry, a depth past the track cap, or a
749	    /// value out of range (`pasted clip N: …`, N the payload's id).
750	    pub fn paste(&self, at: Ticks, track: Option<u32>, payload: &Value) -> Result<Outcome, String> {
751	        let payload = parse_payload(payload)?;
752	        // An explicit destination is an id from THIS project, so an unknown
753	        // one is a caller bug and an error — unlike anything in the payload.
754	        // `tracks.len() - 1` is the front (index 0 is the back, spec §6); a
755	        // project with no tracks at all leaves it at -1, and the deficit
756	        // below adds the one every clip then needs.
757	        let base = match track {
758	            Some(id) => self.require_track_index(id)? as i64,
759	            None => self.tracks.len() as i64 - 1,
760	        };
761	        if payload.clips.is_empty() {
762	            return Ok(Outcome::Identity);
763	        }
764	        let deepest = payload.clips.iter().map(|c| c.track).max().unwrap_or(0) as i64;
765	        // Bounded BEFORE anything is allocated: `track` is a depth here, and
766	        // a payload claiming depth 4 000 000 000 would otherwise ask for four
767	        // billion tracks before `check_caps` ever saw the result.
768	        if deepest >= MAX_TRACKS as i64 {
769	            return Err(format!(
770	                "a pasted clip is {deepest} tracks deep, past the {MAX_TRACKS}-track limit"
771	            ));
772	        }
773	        let at = self.snapped(at).max(0);
774	
775	        let mut next = self.clone();
776	        // The nests first, because their clips name media too: everything
777	        // that will land is resolved against `media[]` in one pass, and the
778	        // nests are then copied in with those ids already mapped.
779	        let nests = reachable_nests(&payload)?;
780	        let landing: Vec<&Clip> = payload
781	            .clips
782	            .iter()
783	            .chain(nests.iter().flat_map(|n| n.clips.iter()))
784	            .collect();
785	        let (sources, looks) = wanted_media(&landing, &payload);
786	        let media = absorb_media(&mut next, &payload, &sources, &looks)?;
787	        let nests = absorb_nests(&mut next, &nests, &media)?;
788	
789	        // Tracks missing behind the destination. Inserting at index 0 shifts
790	        // every existing track up, so the destination index moves with them.
791	        let base = next.add_tracks_behind(deepest, base);
792	
793	        // The earliest clip lands ON `at`, so every other one keeps its own
794	        // distance from it. Offsets are non-negative by construction, which
795	        // is what keeps a paste at 0 from folding clips onto each other.
796	        let earliest = payload.clips.iter().map(|c| c.start).min().unwrap_or(0);
797	
798	        // Back-most depth first, then time: the order clips are placed in is
799	        // the order the overlap rule sees them, so it has to be deterministic
800	        // or the same payload could land two ways.
801	        let mut ordered: Vec<&Clip> = payload.clips.iter().collect();
802	        ordered.sort_by_key(|c| (std::cmp::Reverse(c.track), c.start, c.id));
803	
804	        let mut landing = Landing::new(base);
805	        let first = next.clips.len();
806	        let mut fresh: HashMap<u32, u32> = HashMap::new();
807	        for source in ordered {
808	            let mut clip = source.clone();
809	            next.remint(&mut clip);
810	            fresh.insert(source.id, clip.id);
811	            clip.source = remap_source(&source.source, &media, &nests);
812	            remap_look_media(&mut clip, &media);
813	            remap_hide_silent(&mut clip, &media);
814	            // The payload is trusted about WHAT a clip is and checked about
815	            // what it would do to the project, so a nonsense rate — which
816	            // only a hand-written payload can carry — falls back to 1:1
817	            // rather than reaching the bound below and the composition.
818	            if !(clip.speed.is_finite() && clip.speed > 0.0) {
819	                clip.speed = 1.0;
820	            }
821	            clip.start = at.saturating_add(source.start.saturating_sub(earliest));
822	            // Checked on what the payload sent, before any snap (issue #62).
823	            next.normalise_and_check_pasted(&mut clip, source.id)?;
824	            // `next` and not `self`: the media this clip names was absorbed
825	            // into it above, and only a project that HOLDS the media can
826	            // measure how much window is left (spec §11, D4-4).
827	            next.resnap_clip_times(&mut clip);
828	
829	            // The target track, then the fallbacks already added, then a new
830	            // one.
831	            landing.land(&mut next, clip, source.track as i64);
832	        }
833	        // A payload pair re-pairs through the fresh ids (spec §11 AU-96).
834	        if let Some(landed) = next.clips.get_mut(first..) {
835	            relink_copies(landed, &fresh);
836	        }
837	
838	        self.finish_placement(next, landing.touched())
839	    }
840	}
