    /// Removes the named clips. Gaps stay — rippling is `edit_time`'s job
    /// (spec §6). A picture takes its linked sound with it; a linked sound
    /// named alone goes alone (spec §11 AU-91, `delete_closure`).
    pub fn delete_clips(&self, clips: &[u32]) -> Result<Outcome, String> {
        let ids = self.delete_closure(clips)?;
        if ids.is_empty() {
            return Ok(Outcome::Identity);
        }
        let mut next = self.clone();
        next.clips.retain(|c| !ids.contains(&c.id));
        self.finish(next)
    }

    /// Copies the named clips immediately after their own span, on their
    /// own tracks (spec §6): the copies start one span-length later, so a
    /// multi-clip selection keeps its internal timing exactly.
    ///
    /// Clips and their actions get fresh ids, and a linked partner is
    /// copied too, the copies linked to each other (spec §11 AU-96).
    /// Refuses when the copies would break the overlap rule.
    pub fn duplicate_clips(&self, clips: &[u32]) -> Result<Outcome, String> {
        let selection: Vec<Clip> = self
            .selected_clips(&self.with_links(clips)?)?
            .into_iter()
            .cloned()
            .collect::<Vec<Clip>>();
        if selection.is_empty() {
            return Ok(Outcome::Identity);
        }
        let span_start = selection.iter().map(|c| c.start).min().unwrap_or(0);
        let span_end = selection.iter().map(clip_end).max().unwrap_or(0);
        let delta = span_end.saturating_sub(span_start);
        if delta <= 0 {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        let mut copies: Vec<Clip> = Vec::new();
        let mut fresh: HashMap<u32, u32> = HashMap::new();
        for clip in &selection {
            let mut copy = clip.clone();
            next.remint(&mut copy);
            fresh.insert(clip.id, copy.id);
            copy.start = clip.start.saturating_add(delta);
            copies.push(copy);
        }
        relink_copies(&mut copies, &fresh);
        self.commit_additions(next, copies)
    }

    // ---- reversal ---------------------------------------------------------

    /// Plays a media clip back to front, or forward again (spec §6).
    ///
    /// The core does no pixel work, so this only records a FACT about the
    /// clip: neither the plan nor the recipe changes, and Swift resolves it
    /// by substituting a pre-rendered reversed asset for this media's
    /// segments (spec §11).
    ///
    /// The in point is left exactly where it is, and that is the whole
    /// subtlety: `in` is measured in the stream the clip PLAYS
    /// (`model::Source::Media`), so reversing keeps the in point and
    /// therefore shows different frames — the tail of the file instead of
    /// its head. Advancing it to keep the same frames would be a second
    /// convention, and every trim, split and `source_window.rs`'s
    /// `source_length_on_timeline` would need to know which one was in
    /// force.
    ///
    /// A non-media source is an `Err` and not a refusal — the non-media
    /// rule (`edit.rs`, Results). An identity when the clip already plays
    /// that way. Refused on a linked clip (spec §11 AU-94).
    pub fn set_reversed(&self, clip: u32, reversed: bool) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?;
        let Source::Media {
            media,
            r#in,
            reversed: current,
        } = target.source
        else {
            return Err(format!("clip {clip} is not a media clip"));
        };
        if current == reversed {
            return Ok(Outcome::Identity);
        }

        let mut after = target.clone();
        after.source = Source::Media {
            media,
            r#in,
            reversed,
        };
        if let Some(why) = self.linked_rate_refusal(target, &after) {
            return Ok(Outcome::Refused(why));
        }
        let mut next = self.clone();
        if let Some(slot) = next.clip_mut(clip) {
            *slot = after;
        }
        self.finish(next)
    }
}
//! **On a matte track it is inert** ([`Project::inert_adjustment`]): a
//! matte group is one track, and two clips on one track share an instant
//! only in a transition, which is refused, so the clip could only be the
//! group's sole member and would act as an EMPTY matte. The recipe leaves
//! it out before the mattes are answered. On a track CUT by a matte it
//! grades only inside the matte, which needs nothing here: the compositor
//! weights its pass by the coverage like any matted layer's.
//!
//! Its stored transform, crop, corner, shadow, reflection, chroma,
//! spotlight, obscure and motion placement are kept and do nothing;
//! refusing them would make Paste Attributes fail from any moved clip.
//!
//! **The qualifier is its alone** (spec §11 GR-13): `video.qualifier`
//! narrows which of the destination's pixels the pass grades, read before
//! the grade. On any other clip a non-neutral one is an error in its own
//! sentence ([`check_qualifier_clip`], beside `check_adjustment_video` in
//! `set_video`, `paste` and `paste_attributes`); one reached through a file
//! or an action's end on another clip is inert, because the recipe
//! publishes it only in an adjustment source (`recipe.rs`'s
//! `layer_source`). Paste Attributes drops it onto a picture clip, and an
//! adjustment target keeps its own when the payload clip is not an
//! adjustment clip (`edit_paste_attributes.rs`'s `copy_group`).

use crate::edit_described::Described;
use crate::model::{BlendMode, Clip, FilterKind, Project, Source, VideoProps};
use crate::nest::Instance;
use crate::outcome::Outcome;
use crate::time::Ticks;

impl Project {
    /// An adjustment clip at `at` on `track`, five seconds long unless
    /// `duration` says otherwise, at scale 1 with default `video` (spec §6,
    /// §11 GR-6). Placed through `add_described_clip`, so the overlap rule
    /// and its sentence are the same as any sourceless clip's — with the
    /// adjustment clause, since no overlap may hold one.
    pub fn add_adjustment_clip(
        &self,
        track: u32,
        at: Ticks,
        duration: Option<Ticks>,
    ) -> Result<Outcome, String> {
        self.add_described_clip(
            track,
            at,
            duration,
            Described {
                source: Source::Adjustment,
                scale: 1.0,
                text: None,
                shape: None,
                graphic: None,
            },
        )
    }

    /// Whether `instance` is an adjustment clip on a top-level matte track,
    /// which draws nothing and cuts nothing (this module's doc): the recipe
    /// drops it before `frame_mattes` sees it.
    pub(crate) fn inert_adjustment(&self, instance: &Instance) -> bool {
        is_adjustment(instance.clip)
            && instance.inside.is_empty()
            && !instance.track.matte.is_none()
    }
}

/// Whether the clip is an adjustment clip.
pub(crate) fn is_adjustment(clip: &Clip) -> bool {
    matches!(clip.source, Source::Adjustment)
}

