    /// a second copy of that rule, free to drift from the one the writes go
    /// through.
    static func hasAudio(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        guard clip.enabled.audio else { return false }
        if case .nest = clip.source { return clip.audio != nil }
        guard let media = snapshot.media(for: clip) else { return false }
        return media.hasAudio
    }

    /// Whether the clip's rectangle comes from a decoded source — the clips
    /// that get Crop, Colour and Corner Radius. Text and shape clips get
    /// Transform, Opacity and Shadow only (§4.3).
    static func hasSourcePixels(_ clip: ClipSnapshot, in snapshot: ProjectSnapshot) -> Bool {
        switch clip.source {
        case .media, .still, .image: return true
        case .text, .shape, .graphic, .nest, .adjustment: return false
        }
    }

    /// refreshed but not rebuilt, which shows up as controls that never
    /// appear.
    ///
    /// The two halves are added on top of them all, because whether the
    /// selection has PIXELS and whether it has AUDIO each add or remove a
    /// whole group of sections while every clip id stays exactly as it was.
    /// The audio half is the one that moves under an edit: `hasAudio` reads
    /// `clip.enabled.audio`, so Detach Audio changes it, and so does the
    /// agent's `set_enabled` (§6), which no UI control sends. The video half does NOT track that flag —
    /// `hasPixels` asks the MEDIA whether it has a video track, not the clip
    /// whether its video is on — so what moves it is a relink or a consolidate
    /// that puts different media under the clip. Both are cheap to ask and
    /// neither is visible in the four panes' own signatures.
    override var structureSignature: String {
        [
            super.structureSignature,
            videoPane.structureSignature,
            textPane.structureSignature,
            shapePane.structureSignature,
            graphicPane.structureSignature,
            audioPane.structureSignature,
        }
    }

    /// True when the clip contributes samples. Deliberately the same test
    /// `TimelineView.hasAudio` makes — a nest sings when the core gave it
    /// audio props — so a lane is called audio for exactly the reason its
    /// clips draw waveforms.
    private static func carriesAudio(_ clip: ClipSnapshot, index: SnapshotIndex) -> Bool {
        guard clip.enabled.audio else { return false }
        if case .nest = clip.source { return clip.audio != nil }
        return index.media(for: clip)?.hasAudio ?? false
    }

    /// True when the clip draws pixels. Wider than `TimelineView.hasVideo`,
    /// which answers "is there a filmstrip": a text, shape or nest clip has no
    /// thumbnails but is unquestionably picture, and a lane of them must not
    /// be sized as if it were sound.
    private static func carriesVideo(_ clip: ClipSnapshot, index: SnapshotIndex) -> Bool {
        guard clip.enabled.video else { return false }
        switch clip.source {
        case .media, .still, .image: return index.media(for: clip)?.hasVideo ?? false
        case .text, .shape, .graphic, .nest, .adjustment: return true
        }
    }

